import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";

const VERSION = "R9.2.0";
const FILES = [{"path":"src/features/music/MusicMiniPlayer.tsx","baseline":"68bc24bbd98968ff6d4224265d710c0f9e9e695a302ec41bbb6798d713178b0f","desired":"0bc32976ec34498a2360b8eefa49763e872e4620c2cd09e1fae52e7af8d6b7d2","payload":""},{"path":"src/lib/musicPlayer.ts","baseline":"82a5cc8f8935f8d12629b190894b2ca643d72f79bd87857a75406fcc69435f72","desired":"a431dc54593444140a9d6eea5bce36e415aecf52d018020fccdfd5cfba818c2a","payload":""},{"path":"src/features/progress/ProgressPage.tsx","baseline":"fefa39eb57ae249364545dc1cf56a6337544733238e5e828d8b0881a0151b758","desired":"8eb5b10581087adc6f36f53ca35d8d7b2d0cb44dabd1609b6aab50f0f288014d","payload":""}];

function normalize(text) { return text.replace(/\r\n/g, "\n"); }
function hashText(text) { return crypto.createHash("sha256").update(normalize(text)).digest("hex"); }
function findRoot(start) {
  let dir = path.resolve(start);
  for (let i = 0; i < 8; i += 1) {
    if (fs.existsSync(path.join(dir, "package.json")) && fs.existsSync(path.join(dir, "src"))) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error("Could not find the MVPTrainerPro-Personal project root. Run this installer from the repo or its scripts folder.");
}

try {
  const root = findRoot(process.cwd());
  console.log(`MVP Trainer V5 ${VERSION} DSP Reliability + Progress Clarity`);
  console.log(`Project: ${root}`);

  const staged = [];
  for (const file of FILES) {
    const target = path.join(root, file.path);
    if (!fs.existsSync(target)) throw new Error(`Missing ${file.path}`);
    const current = fs.readFileSync(target, "utf8");
    const currentHash = hashText(current);
    const replacement = zlib.gunzipSync(Buffer.from(file.payload, "base64")).toString("utf8");
    const desiredHash = hashText(replacement);
    if (desiredHash !== file.desired) throw new Error(`Embedded replacement verification failed for ${file.path}.`);
    if (currentHash === file.desired) { staged.push({...file,target,replacement,already:true}); continue; }
    if (currentHash !== file.baseline) {
      console.error("Installer stopped before changing anything.");
      console.error(`Refusing to overwrite ${file.path} because it is not the audited baseline.`);
      console.error(`Found normalized SHA-256: ${currentHash}`);
      console.error(`Expected baseline SHA-256: ${file.baseline}`);
      process.exit(2);
    }
    staged.push({...file,target,replacement,already:false});
  }

  if (staged.every((file) => file.already)) {
    console.log("Already installed. No changes needed.");
    process.exit(0);
  }

  const written = [];
  try {
    for (const file of staged) {
      if (file.already) continue;
      const backup = `${file.target}.pre-r9-2-0.bak`;
      if (!fs.existsSync(backup)) fs.copyFileSync(file.target, backup);
      fs.writeFileSync(file.target, file.replacement, "utf8");
      if (hashText(fs.readFileSync(file.target, "utf8")) !== file.desired) throw new Error(`Post-write verification failed for ${file.path}.`);
      written.push({...file,backup});
    }
  } catch (error) {
    for (const file of written.reverse()) { try { fs.copyFileSync(file.backup, file.target); } catch {} }
    throw error;
  }

  console.log("Applied successfully:");
  console.log("  + OUTPUT first on desktop and mobile");
  console.log("  + Mobile EQ workspace restored and protected");
  console.log("  + Advanced Trim corrected to -12 dB .. +6 dB with truthful gain mapping");
  console.log("  + 80-100% volume range upgraded to protected high-output reserve");
  console.log("  + Studio headphone immersion upgraded to dual virtual-loudspeaker HRTF rendering");
  console.log("  + HRTF stage feeds the existing Studio WASM mastering and true-peak limiter");
  console.log("  + Dynamics/output telemetry labels corrected");
  console.log("  + Progress bodyweight chart now labels daily weight vs rolling trend");
  console.log("  + Progress chart marks START/CURRENT and explains change in plain English");
  console.log("Backups use the .pre-r9-2-0.bak suffix.");
  console.log("Next: npm run build");
} catch (error) {
  console.error(`MVP Trainer V5 ${VERSION} installer stopped:`);
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
